SELECT 
FROM sys_flow_comment_phrase p

    p.tenant_id = #{tenantId}
    AND p.del_flag = 0
    AND p.owner_type = #{ownerType}
    AND p.user_id = #{userId}

        AND p.content LIKE CONCAT('%', #{keyword}, '%')


        AND p.scene = #{scene}


        AND p.status = #{status}


ORDER BY p.sort_order ASC, p.id ASC

SELECT 
FROM sys_flow_comment_phrase p
WHERE p.id = #{id}
  AND p.tenant_id = #{tenantId}
  AND p.del_flag = 0
LIMIT 1

SELECT 
FROM sys_flow_comment_phrase p
WHERE p.id = #{id}
  AND p.tenant_id = #{tenantId}
  AND p.del_flag = 0
LIMIT 1

SELECT COUNT(1)
FROM sys_flow_comment_phrase
WHERE tenant_id = #{tenantId}
  AND owner_type = #{ownerType}
  AND user_id = #{userId}
  AND scene = #{scene}
  AND content = #{content}
  AND del_flag = 0

      AND id != #{excludeId}

SELECT COUNT(1)
FROM sys_flow_comment_phrase
WHERE tenant_id = #{tenantId}
  AND owner_type = #{ownerType}
  AND user_id = #{userId}
  AND del_flag = 0

