UPDATE sys_flow_comment_phrase
SET content = #{phrase.content},
    scene = #{phrase.scene},
    sort_order = #{phrase.sortOrder},
    status = #{phrase.status},
    update_by = #{phrase.updateBy},
    update_time = #{phrase.updateTime}
WHERE id = #{phrase.id}
  AND tenant_id = #{tenantId}
  AND del_flag = 0
